    /// <summary>Safety-only sample: e-stop, deadman, mode, and link, plus identity. A schema-valid sample is not permission to skip the producer safety gate. Missing safety fields are invalid and must not be treated as a permit.</summary>
    [JsonObject(MemberSerialization = MemberSerialization.OptIn)]
    public sealed class SafetyState
    {
        /// <summary>Telemetry schema semver MAJOR.MINOR.PATCH. Minor versions only add optional fields. Major versions break. This schema accepts 1.0.x.</summary>
        [JsonProperty("v", Required = Required.Always)]
        public string V { get; set; }

        /// <summary>Seconds since the Unix epoch (UTC). SI second, not a ROS stamp and not milliseconds.</summary>
        [JsonProperty("t", Required = Required.Always)]
        public double T { get; set; }

        /// <summary>Stable robot identifier. Required on every sample so streams cannot be mixed.</summary>
        [JsonProperty("robot_id", Required = Required.Always)]
        public string RobotId { get; set; }

        /// <summary>sim is a simulator. real is a physical robot. Required so a simulated sample cannot be read as hardware.</summary>
        [JsonProperty("kind", Required = Required.Always)]
        public RobotKind Kind { get; set; }

        /// <summary>Base and arm modes. Both are required. A robot with no arm sends arm not_present rather than omitting it. fault on either subsystem is not a motion permit.</summary>
        [JsonProperty("mode", Required = Required.Always)]
        public ModeState Mode { get; set; }

        /// <summary>E-stop report. Motion must not be commanded when active or latched is true. There is no default that means clear.</summary>
        [JsonProperty("estop", Required = Required.Always)]
        public EstopState Estop { get; set; }

        /// <summary>Operator deadman permit. True only while the deadman control is asserted. False is not a permit. Omitting the field is invalid and must not be read as true.</summary>
        [JsonProperty("deadman", Required = Required.Always)]
        public bool Deadman { get; set; }

        /// <summary>Link that carried this sample. Required even when the stream is dead: use hz 0. Do not omit link to mean disconnected.</summary>
        [JsonProperty("link", Required = Required.Always)]
        public LinkStatus Link { get; set; }

        /// <summary>Throws when this object does not satisfy the schema constraints.</summary>
        public void Validate()
        {
            OhhoValidate.Text("v", V, true, null, null, @"^1\.0\.(0|[1-9]\d*)$");
            OhhoValidate.Finite("t", T, 0d, null);
            OhhoValidate.Text("robot_id", RobotId, true, 1, 128, @"^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$");
            if (Mode == null)
            {
                throw new InvalidOperationException("mode is required");
            }
            Mode.Validate();
            if (Estop == null)
            {
                throw new InvalidOperationException("estop is required");
            }
            Estop.Validate();
            if (Link == null)
            {
                throw new InvalidOperationException("link is required");
            }
            Link.Validate();
        }

        /// <summary>Deserialize and validate. Unknown fields and explicit nulls are errors.</summary>
        public static SafetyState Parse(string json)
        {
            if (json == null)
            {
                throw new ArgumentNullException(nameof(json));
            }
            SafetyState value = JsonConvert.DeserializeObject<SafetyState>(json, OhhoJson.Settings);
            if (value == null)
            {
                throw new JsonSerializationException("SafetyState JSON was null.");
            }
            value.Validate();
            return value;
        }

        /// <summary>
        /// True only when deadman is asserted, e-stop is clear and unlatched with source none,
        /// and neither subsystem mode is fault. Missing flags return false.
        /// This is not a safety gate: it does not apply caps, joint limits, watchdogs, or staleness.
        /// </summary>
        public bool SafetyFlagsAllowMotion()
        {
            if (Estop == null || Mode == null)
            {
                return false;
            }
            if (!Deadman)
            {
                return false;
            }
            if (Estop.Active)
            {
                return false;
            }
            if (Estop.Latched)
            {
                return false;
            }
            if (Estop.Source != EstopSource.None)
            {
                return false;
            }
            if (Mode.Base == SubsystemMode.Fault || Mode.Arm == SubsystemMode.Fault)
            {
                return false;
            }
            return true;
        }
    }

